    void test_native_builtin_methods_reflect_through_pemstatus_getpem_and_amembers()
    {
        namespace fs = std::filesystem;
        const fs::path temp_root = fs::temp_directory_path() / "copperfin_native_prg_builtin_method_reflection";
        std::error_code ignored;
        fs::remove_all(temp_root, ignored);
        fs::create_directories(temp_root);

        const fs::path main_path = temp_root / "native_builtin_method_reflection.prg";
        write_text(
            main_path,
            "oForm = CREATEOBJECT('MainForm')\n"
            "lHasRelease = PEMSTATUS(oForm, 'Release', 1)\n"
            "lHasRefresh = PEMSTATUS(oForm, 'Refresh', 1)\n"
            "lHasMove = PEMSTATUS(oForm, 'Move', 1)\n"
            "lHasShow = PEMSTATUS(oForm, 'Show', 1)\n"
            "lHasHide = PEMSTATUS(oForm, 'Hide', 1)\n"
            "lHasReset = PEMSTATUS(oForm, 'ResetToDefault', 1)\n"
            "lHasTextSetFocus = PEMSTATUS(oForm.txtName, 'SetFocus', 1)\n"
            "lReleaseReadOnly = PEMSTATUS(oForm, 'Release', 5)\n"
            "lMoveReadOnly = PEMSTATUS(oForm, 'Move', 5)\n"
            "lShowReadOnly = PEMSTATUS(oForm, 'Show', 5)\n"
            "lResetReadOnly = PEMSTATUS(oForm, 'ResetToDefault', 5)\n"
            "lTextSetFocusReadOnly = PEMSTATUS(oForm.txtName, 'SetFocus', 5)\n"
            "lGetRelease = GETPEM(oForm, 'Release')\n"
            "lGetMove = GETPEM(oForm, 'Move')\n"
            "lGetShow = GETPEM(oForm, 'Show')\n"
            "lGetReset = GETPEM(oForm, 'ResetToDefault')\n"
            "lGetTextSetFocus = GETPEM(oForm.txtName, 'SetFocus')\n"
            "nFormMethods = AMEMBERS(aFormMethods, oForm, 2)\n"
            "nFormUnion = AMEMBERS(aFormUnion, oForm, 3)\n"
            "nTextMethods = AMEMBERS(aTextMethods, oForm.txtName, 2)\n"
            "nFormHasRelease = ASCAN(aFormMethods, 'RELEASE')\n"
            "nFormHasMove = ASCAN(aFormMethods, 'MOVE')\n"
            "nFormHasRefresh = ASCAN(aFormMethods, 'REFRESH')\n"
            "nFormHasShow = ASCAN(aFormMethods, 'SHOW')\n"
            "nFormHasHide = ASCAN(aFormMethods, 'HIDE')\n"
            "nFormUnionHasReset = ASCAN(aFormUnion, 'RESETTODEFAULT')\n"
            "nTextHasSetFocus = ASCAN(aTextMethods, 'SETFOCUS')\n"
            "RETURN\n"
            "DEFINE CLASS MainForm AS Form\n"
            "    ADD OBJECT txtName AS TextBox\n"
            "ENDDEFINE\n");

        copperfin::runtime::PrgRuntimeSession session =
            copperfin::runtime::PrgRuntimeSession::create(make_runtime_session_options(main_path.string(), temp_root.string()));

        const auto state = session.run(copperfin::runtime::DebugResumeAction::continue_run);
        expect(state.completed,
               std::string("native builtin-method reflection script should complete: ") + state.message +
                   " @line=" + std::to_string(state.location.line));

        const auto check = [&](const std::string &name, const std::string &expected)
        {
            const auto it = state.globals.find(name);
            expect(it != state.globals.end(), name + " variable not found");
            if (it != state.globals.end())
            {
                expect(copperfin::runtime::format_value(it->second) == expected,
                       name + " expected '" + expected + "' got '" +
                           copperfin::runtime::format_value(it->second) + "'");
            }
        };

        check("lhasrelease", "true");
        check("lhasrefresh", "true");
        check("lhasmove", "true");
        check("lhasshow", "true");
        check("lhashide", "true");
        check("lhasreset", "true");
        check("lhastextsetfocus", "true");
        check("lreleasereadonly", "false");
        check("lmovereadonly", "false");
        check("lshowreadonly", "false");
        check("lresetreadonly", "false");
        check("ltextsetfocusreadonly", "false");
        check("lgetrelease", "true");
        check("lgetmove", "true");
        check("lgetshow", "true");
        check("lgetreset", "true");
        check("lgettextsetfocus", "true");

        const auto expect_positive = [&](const std::string &name, const std::string &message)
        {
            const auto it = state.globals.find(name);
            expect(it != state.globals.end(), name + " variable not found");
            if (it != state.globals.end())
            {
                expect(copperfin::runtime::format_value(it->second) != "0",
                       message + " expected a positive ASCAN() result");
            }
        };

        expect_positive("nformhasrelease",
                        "AMEMBERS(..., 2) should expose the shipped native Release builtin");
        expect_positive("nformhasmove",
                        "AMEMBERS(..., 2) should expose the shipped native Move builtin");
        expect_positive("nformhasrefresh",
                        "AMEMBERS(..., 2) should expose the shipped native Refresh builtin");
        expect_positive("nformhasshow",
                        "AMEMBERS(..., 2) should expose the shipped native Show builtin");
        expect_positive("nformhashide",
                        "AMEMBERS(..., 2) should expose the shipped native Hide builtin");
        expect_positive("nformunionhasreset",
                        "AMEMBERS(..., 3) should expose the shipped native ResetToDefault builtin");
        expect_positive("ntexthassetfocus",
                        "AMEMBERS(..., 2) should expose the shipped native SetFocus builtin");

        fs::remove_all(temp_root, ignored);
    }

    void test_same_prg_native_bare_helper_calls_resolve_to_current_instance_before_top_level_routines()
    {
        namespace fs = std::filesystem;
        const fs::path temp_root = fs::temp_directory_path() / "copperfin_native_prg_helper_calls";
        std::error_code ignored;
        fs::remove_all(temp_root, ignored);
        fs::create_directories(temp_root);

        const fs::path main_path = temp_root / "native_helper_calls.prg";
        write_text(
            main_path,
            "nSeed = 4\n"
            "oCreate = CREATEOBJECT('ChildWidget', @nSeed)\n"
            "oPlain = CREATEOBJECT('Empty')\n"
            "oDict = NEWOBJECT('Scripting.Dictionary', 'vbscript.dll')\n"
            "oPlain.Extra = 'plain'\n"
            "lDictSet = SETPEM(oDict, 'comparemode', 8)\n"
            "nDictCompare = GETPEM(oDict, 'comparemode')\n"
            "cDescribe = oCreate.Describe('prefix')\n"
            "nSeedAfter = nSeed\n"
            "cCaption = oCreate.Caption\n"
            "nStored = oCreate.nValue\n"
            "lInitRan = oCreate.lInitRan\n"
            "cPlain = oPlain.Extra\n"
            "RETURN\n"
            "FUNCTION BuildCaption\n"
            "    LPARAMETERS tcPrefix\n"
            "    RETURN 'top-level-' + tcPrefix\n"
            "ENDFUNC\n"
            "DEFINE CLASS ParentWidget AS Custom\n"
            "    Caption = 'Parent'\n"
            "    nValue = 0\n"
            "    lInitRan = .F.\n"
            "    PROCEDURE Init\n"
            "        LPARAMETERS tnSeed\n"
            "        FinishInit(@tnSeed)\n"
            "        RETURN THIS.Caption\n"
            "    ENDPROC\n"
            "    PROCEDURE FinishInit\n"
            "        LPARAMETERS tnSeed\n"
            "        tnSeed = tnSeed + 3\n"
            "        THIS.nValue = tnSeed\n"
            "        THIS.Caption = THIS.Caption + '-Init'\n"
            "        THIS.lInitRan = .T.\n"
            "        RETURN\n"
            "    ENDPROC\n"
            "    FUNCTION Describe\n"
            "        LPARAMETERS tcPrefix\n"
            "        RETURN BuildCaption(tcPrefix)\n"
            "    ENDFUNC\n"
            "    FUNCTION BuildCaption\n"
            "        LPARAMETERS tcPrefix\n"
            "        RETURN tcPrefix + ':' + THIS.Caption\n"
            "    ENDFUNC\n"
            "ENDDEFINE\n"
            "DEFINE CLASS ChildWidget AS ParentWidget\n"
            "    Caption = 'Child'\n"
            "ENDDEFINE\n");

        copperfin::runtime::PrgRuntimeSession session =
            copperfin::runtime::PrgRuntimeSession::create(make_runtime_session_options(main_path.string(), temp_root.string()));

        const auto state = session.run(copperfin::runtime::DebugResumeAction::continue_run);
        expect(state.completed,
               std::string("native bare helper-call script should complete: ") + state.message +
                   " @line=" + std::to_string(state.location.line));

        const auto check = [&](const std::string &name, const std::string &expected)
        {
            const auto it = state.globals.find(name);
            if (it == state.globals.end())
            {
                expect(false, name + " variable not found");
                return;
            }
            expect(copperfin::runtime::format_value(it->second) == expected,
                   name + " expected '" + expected + "' got '" + copperfin::runtime::format_value(it->second) + "'");
        };

        check("cdescribe", "prefix:Child-Init");
        check("nseedafter", "7");
        check("ccaption", "Child-Init");
        check("nstored", "7");
        check("linitran", "true");
        check("cplain", "plain");
        check("ldictset", "true");
        check("ndictcompare", "8");

        expect(state.ole_objects.size() == 3U,
               "native bare helper-call script should register native, plain, and COM objects");
        if (state.ole_objects.size() == 3U)
        {
            const auto &native_object = state.ole_objects[0];
            expect(native_object.prog_id == "ChildWidget",
                   "native bare helper-call resolution should preserve child class identity");
            const auto caption = native_object.properties.find("caption");
            const auto value = native_object.properties.find("nvalue");
            const auto init_ran = native_object.properties.find("linitran");
            if (caption != native_object.properties.end())
            {
                expect(copperfin::runtime::format_value(caption->second) == "Child-Init",
                       "native bare helper-call resolution should preserve helper-updated caption state");
            }
            else
            {
                expect(false, "native bare helper-call resolution should materialize helper-updated caption state");
            }
            if (value != native_object.properties.end())
            {
                expect(copperfin::runtime::format_value(value->second) == "7",
                       "native bare helper-call resolution should preserve helper by-reference updates from Init");
            }
            else
            {
                expect(false, "native bare helper-call resolution should materialize helper-updated numeric state");
            }
            if (init_ran != native_object.properties.end())
            {
                expect(copperfin::runtime::format_value(init_ran->second) == "true",
                       "native bare helper-call resolution should preserve helper-set Init flags");
            }
            else
            {
                expect(false, "native bare helper-call resolution should materialize helper-set Init flags");
            }

            expect(state.ole_objects[1].prog_id == "Empty",
                   "plain CREATEOBJECT should remain stable while native helper-method resolution lands");
            expect(state.ole_objects[2].prog_id == "Scripting.Dictionary",
                   "COM NEWOBJECT should remain stable while native helper-method resolution lands");
        }

        const bool has_helper_invoke_event = std::any_of(state.events.begin(), state.events.end(), [](const auto &event)
        {
            return event.category == "prg.object.invoke" &&
                   (event.detail == "ParentWidget.FinishInit" ||
                    event.detail == "ParentWidget.BuildCaption");
        });
        expect(has_helper_invoke_event,
               "native bare helper-call resolution should emit helper-method invoke events");

        fs::remove_all(temp_root, ignored);
    }

