    void test_external_prg_base_methods_support_dodefault_dispatch()
    {
        namespace fs = std::filesystem;
        const fs::path temp_root = fs::temp_directory_path() / "copperfin_native_prg_external_base_dodefault";
        std::error_code ignored;
        fs::remove_all(temp_root, ignored);
        fs::create_directories(temp_root);

        const fs::path library_path = temp_root / "widgetlib.prg";
        write_text(
            library_path,
            "DEFINE CLASS ParentWidget AS Custom\n"
            "    Caption = 'Parent'\n"
            "    nValue = 0\n"
            "    lParentInit = .F.\n"
            "    PROCEDURE Init\n"
            "        LPARAMETERS tnSeed\n"
            "        tnSeed = tnSeed + 2\n"
            "        THIS.nValue = tnSeed\n"
            "        THIS.Caption = THIS.Caption + '-P'\n"
            "        THIS.lParentInit = .T.\n"
            "        RETURN THIS.Caption\n"
            "    ENDPROC\n"
            "    FUNCTION Describe\n"
            "        LPARAMETERS tcPrefix\n"
            "        RETURN tcPrefix + ':' + THIS.Caption\n"
            "    ENDFUNC\n"
            "    FUNCTION Who\n"
            "        RETURN 'Parent'\n"
            "    ENDFUNC\n"
            "ENDDEFINE\n");

        const fs::path main_path = temp_root / "external_base_dodefault.prg";
        write_text(
            main_path,
            "nSeed = 5\n"
            "oCreate = CREATEOBJECT('ChildWidget', @nSeed)\n"
            "oPlain = CREATEOBJECT('Empty')\n"
            "oDict = NEWOBJECT('Scripting.Dictionary', 'vbscript.dll')\n"
            "oPlain.Extra = 'plain'\n"
            "lDictSet = SETPEM(oDict, 'comparemode', 20)\n"
            "nDictCompare = GETPEM(oDict, 'comparemode')\n"
            "cDescribe = oCreate.Describe('prefix')\n"
            "cWho = oCreate.Who()\n"
            "nSeedAfter = nSeed\n"
            "cCaption = oCreate.Caption\n"
            "nStored = oCreate.nValue\n"
            "lParentInit = oCreate.lParentInit\n"
            "lChildInit = oCreate.lChildInit\n"
            "cPlain = oPlain.Extra\n"
            "RETURN\n"
            "DEFINE CLASS ChildWidget AS ParentWidget OF widgetlib.prg\n"
            "    Caption = 'Child'\n"
            "    lChildInit = .F.\n"
            "    PROCEDURE Init\n"
            "        LPARAMETERS tnSeed\n"
            "        LOCAL lcBaseCaption\n"
            "        lcBaseCaption = DODEFAULT(@tnSeed)\n"
            "        THIS.Caption = lcBaseCaption + '-C'\n"
            "        THIS.lChildInit = .T.\n"
            "        RETURN THIS.Caption\n"
            "    ENDPROC\n"
            "    FUNCTION Describe\n"
            "        LPARAMETERS tcPrefix\n"
            "        RETURN DODEFAULT(tcPrefix) + ':Child'\n"
            "    ENDFUNC\n"
            "    FUNCTION Who\n"
            "        RETURN DODEFAULT() + '+Child'\n"
            "    ENDFUNC\n"
            "ENDDEFINE\n");

        copperfin::runtime::PrgRuntimeSession session =
            copperfin::runtime::PrgRuntimeSession::create(make_runtime_session_options(main_path.string(), temp_root.string()));

        const auto state = session.run(copperfin::runtime::DebugResumeAction::continue_run);
        expect(state.completed,
               std::string("external-base DODEFAULT script should complete: ") + state.message +
                   " @line=" + std::to_string(state.location.line));

        const auto check = [&](const std::string &name, const std::string &expected)
        {
            const auto it = state.globals.find(name);
            if (it == state.globals.end())
            {
                expect(false, name + " variable not found");
                return;
            }
            expect(copperfin::runtime::format_value(it->second) == expected,
                   name + " expected '" + expected + "' got '" + copperfin::runtime::format_value(it->second) + "'");
        };

        check("cdescribe", "prefix:Child-P-C:Child");
        check("cwho", "Parent+Child");
        check("nseedafter", "7");
        check("ccaption", "Child-P-C");
        check("nstored", "7");
        check("lparentinit", "true");
        check("lchildinit", "true");
        check("cplain", "plain");
        check("ldictset", "true");
        check("ndictcompare", "20");

        expect(state.ole_objects.size() == 3U,
               "external-base DODEFAULT script should register native, plain, and COM objects");
        if (state.ole_objects.size() == 3U)
        {
            const auto &native_object = state.ole_objects[0];
            expect(native_object.prog_id == "ChildWidget",
                   "external-base DODEFAULT should preserve child class identity");
            const auto caption = native_object.properties.find("caption");
            const auto value = native_object.properties.find("nvalue");
            const auto parent_init = native_object.properties.find("lparentinit");
            const auto child_init = native_object.properties.find("lchildinit");
            expect(caption != native_object.properties.end(),
                   "external-base DODEFAULT should preserve child/base Init-updated caption state");
            expect(value != native_object.properties.end(),
                   "external-base DODEFAULT should preserve by-reference Init-updated numeric state");
            expect(parent_init != native_object.properties.end(),
                   "external-base DODEFAULT should preserve parent Init state");
            expect(child_init != native_object.properties.end(),
                   "external-base DODEFAULT should preserve child Init state");
            if (caption != native_object.properties.end())
            {
                expect(copperfin::runtime::format_value(caption->second) == "Child-P-C",
                       "external-base DODEFAULT should compose child Init logic after the external base Init");
            }
            if (value != native_object.properties.end())
            {
                expect(copperfin::runtime::format_value(value->second) == "7",
                       "external-base DODEFAULT should preserve external base Init by-reference write-back results");
            }
            if (parent_init != native_object.properties.end())
            {
                expect(copperfin::runtime::format_value(parent_init->second) == "true",
                       "external-base DODEFAULT should run the external parent Init through the base-call path");
            }
            if (child_init != native_object.properties.end())
            {
                expect(copperfin::runtime::format_value(child_init->second) == "true",
                       "external-base DODEFAULT should continue child Init logic after the base-call path");
            }

            expect(state.ole_objects[1].prog_id == "Empty",
                   "plain CREATEOBJECT should remain stable while external-base DODEFAULT lands");
            expect(state.ole_objects[2].prog_id == "Scripting.Dictionary",
                   "COM NEWOBJECT should remain stable while external-base DODEFAULT lands");
        }

        const bool has_base_invoke_event = std::any_of(state.events.begin(), state.events.end(), [](const auto &event)
        {
            return event.category == "prg.object.baseinvoke" &&
                   (event.detail == "ParentWidget.Init" ||
                    event.detail == "ParentWidget.Describe" ||
                    event.detail == "ParentWidget.Who");
        });
        expect(has_base_invoke_event,
               "external-base DODEFAULT should emit a base-invoke runtime event");

        fs::remove_all(temp_root, ignored);
    }

    void test_external_prg_base_methods_reflect_through_getpem_pemstatus_and_amembers()
    {
        namespace fs = std::filesystem;
        const fs::path temp_root = fs::temp_directory_path() / "copperfin_native_prg_external_base_method_reflection";
        std::error_code ignored;
        fs::remove_all(temp_root, ignored);
        fs::create_directories(temp_root);

        const fs::path library_path = temp_root / "widgetlib.prg";
        write_text(
            library_path,
            "DEFINE CLASS ParentWidget AS Custom\n"
            "    Caption = 'Parent'\n"
            "    FUNCTION Describe\n"
            "        LPARAMETERS tcPrefix\n"
            "        RETURN tcPrefix + ':' + THIS.Caption\n"
            "    ENDFUNC\n"
            "    FUNCTION Who\n"
            "        RETURN 'Parent'\n"
            "    ENDFUNC\n"
            "ENDDEFINE\n");

        const fs::path main_path = temp_root / "external_base_method_reflection.prg";
        write_text(
            main_path,
            "oCreate = CREATEOBJECT('ChildWidget')\n"
            "oPlain = CREATEOBJECT('Empty')\n"
            "oDict = NEWOBJECT('Scripting.Dictionary', 'vbscript.dll')\n"
            "oPlain.Extra = 'plain'\n"
            "lDictSet = SETPEM(oDict, 'comparemode', 23)\n"
            "nDictCompare = GETPEM(oDict, 'comparemode')\n"
            "lHasDescribe = GETPEM(oCreate, 'Describe')\n"
            "lHasWho = PEMSTATUS(oCreate, 'Who', 1)\n"
            "lHasPing = PEMSTATUS(oCreate, 'Ping', 1)\n"
            "nMembersMethods = AMEMBERS(aMembersMethods, oCreate, 2)\n"
            "cMethod1 = aMembersMethods[1]\n"
            "cMethod2 = aMembersMethods[2]\n"
            "cMethod3 = aMembersMethods[3]\n"
            "cDescribe = oCreate.Describe('prefix')\n"
            "cWho = oCreate.Who()\n"
            "cPing = oCreate.Ping()\n"
            "cPlain = oPlain.Extra\n"
            "RETURN\n"
            "DEFINE CLASS ChildWidget AS ParentWidget OF widgetlib.prg\n"
            "    Caption = 'Child'\n"
            "    FUNCTION Ping\n"
            "        RETURN 'Child'\n"
            "    ENDFUNC\n"
            "ENDDEFINE\n");

        copperfin::runtime::PrgRuntimeSession session =
            copperfin::runtime::PrgRuntimeSession::create(make_runtime_session_options(main_path.string(), temp_root.string()));

        const auto state = session.run(copperfin::runtime::DebugResumeAction::continue_run);
        expect(state.completed,
               std::string("external-base method reflection script should complete: ") + state.message +
                   " @line=" + std::to_string(state.location.line));

        const auto check = [&](const std::string &name, const std::string &expected)
        {
            const auto it = state.globals.find(name);
            if (it == state.globals.end())
            {
                expect(false, name + " variable not found");
                return;
            }
            expect(copperfin::runtime::format_value(it->second) == expected,
                   name + " expected '" + expected + "' got '" + copperfin::runtime::format_value(it->second) + "'");
        };

        check("lhasdescribe", "true");
        check("lhaswho", "true");
        check("lhasping", "true");
        check("nmembersmethods", "10");
        check("cmethod1", "DESCRIBE");
        check("cmethod2", "PING");
        check("cmethod3", "READEXPRESSION");
        check("cdescribe", "prefix:Child");
        check("cwho", "Parent");
        check("cping", "Child");
        check("cplain", "plain");
        check("ldictset", "true");
        check("ndictcompare", "23");

        expect(state.ole_objects.size() == 3U,
               "external-base method reflection should register native, plain, and COM objects");
        if (state.ole_objects.size() == 3U)
        {
            const auto &native_object = state.ole_objects[0];
            expect(native_object.prog_id == "ChildWidget",
                   "external-base method reflection should preserve child class identity");
            expect(native_object.source == main_path.string(),
                   "external-base method reflection should preserve the derived class provenance");
            expect(std::find(native_object.methods.begin(), native_object.methods.end(), "Describe") != native_object.methods.end(),
                   "external-base method reflection should materialize inherited methods in runtime object metadata");
            expect(std::find(native_object.methods.begin(), native_object.methods.end(), "Who") != native_object.methods.end(),
                   "external-base method reflection should preserve external-base methods in runtime object metadata");
            expect(std::find(native_object.methods.begin(), native_object.methods.end(), "Ping") != native_object.methods.end(),
                   "external-base method reflection should preserve derived methods in runtime object metadata");
            expect(state.ole_objects[1].prog_id == "Empty",
                   "plain CREATEOBJECT should remain stable while external-base method reflection lands");
            expect(state.ole_objects[2].prog_id == "Scripting.Dictionary",
                   "COM NEWOBJECT should remain stable while external-base method reflection lands");
        }

        const bool has_invoke_event = std::any_of(state.events.begin(), state.events.end(), [](const auto &event)
        {
            return event.category == "prg.object.invoke" &&
                   (event.detail == "ParentWidget.Describe" ||
                    event.detail == "ParentWidget.Who" ||
                    event.detail == "ChildWidget.Ping");
        });
        expect(has_invoke_event,
               "external-base method reflection should emit inherited and derived method invoke events");

        fs::remove_all(temp_root, ignored);
    }

    void test_same_prg_native_bindevent_raiseevent_and_unbindevents_dispatch_same_session_handlers()
    {
        namespace fs = std::filesystem;
        const fs::path temp_root = fs::temp_directory_path() / "copperfin_native_prg_bindevent";
        std::error_code ignored;
        fs::remove_all(temp_root, ignored);
        fs::create_directories(temp_root);

        const fs::path main_path = temp_root / "native_bindevent.prg";
        write_text(
            main_path,
            "cSequence = ''\n"
            "nBeforeCalls = 0\n"
            "nRoutineCalls = 0\n"
            "nSourceCalls = 0\n"
            "nAfterCalls = 0\n"
            "nAfterSourceCalls = 0\n"
            "nNoSimpleCalls = 0\n"
            "nNoSimpleSourceCalls = 0\n"
            "oSource = CREATEOBJECT('SourceThing')\n"
            "oHandler = CREATEOBJECT('HandlerThing')\n"
            "oPlain = CREATEOBJECT('Empty')\n"
            "oDict = NEWOBJECT('Scripting.Dictionary', 'vbscript.dll')\n"
            "oPlain.Extra = 'plain'\n"
            "lDictSet = SETPEM(oDict, 'comparemode', 29)\n"
            "nDictCompare = GETPEM(oDict, 'comparemode')\n"
            "nBind1 = BINDEVENT(oSource, 'Ping', oHandler, 'HandleBefore', 1)\n"
            "nBind2 = BINDEVENT(oSource, 'Ping', 'HandlePing')\n"
            "nBind3 = BINDEVENT(oSource, 'AfterPing', oHandler, 'HandleAfter')\n"
            "nBind4 = BINDEVENT(oSource, 'NoSimple', oHandler, 'HandleNoSimple', 2)\n"
            "cDirectPing = oSource.Ping(41)\n"
            "lRaisedAfter = RAISEEVENT(oSource, 'AfterPing', 7)\n"
            "cDirectNoSimple = oSource.NoSimple(5)\n"
            "lRaisedNoSimple = RAISEEVENT(oSource, 'NoSimple', 6)\n"
            "nUnbindSpecific = UNBINDEVENTS(oSource, 'Ping', oHandler, 'HandleBefore')\n"
            "lRaisedPingAfterUnbind = RAISEEVENT(oSource, 'Ping', 9)\n"
            "nUnbindObject = UNBINDEVENTS(oHandler)\n"
            "lRaisedAfterAfterObjectUnbind = RAISEEVENT(oSource, 'AfterPing', 8)\n"
            "cPlain = oPlain.Extra\n"
            "RETURN\n"
            "PROCEDURE HandlePing\n"
            "    LPARAMETERS tnValue\n"
            "    cSequence = cSequence + '[routine:' + TRANSFORM(tnValue) + ']'\n"
            "    nRoutineCalls = nRoutineCalls + 1\n"
            "    RETURN\n"
            "ENDPROC\n"
            "DEFINE CLASS SourceThing AS Custom\n"
            "    FUNCTION Ping\n"
            "        LPARAMETERS tnValue\n"
            "        cSequence = cSequence + '[source:' + TRANSFORM(tnValue) + ']'\n"
            "        nSourceCalls = nSourceCalls + 1\n"
            "        RETURN 'ping:' + TRANSFORM(tnValue)\n"
            "    ENDFUNC\n"
            "    FUNCTION AfterPing\n"
            "        LPARAMETERS tnValue\n"
            "        cSequence = cSequence + '[aftersource:' + TRANSFORM(tnValue) + ']'\n"
            "        nAfterSourceCalls = nAfterSourceCalls + 1\n"
            "        RETURN 'after:' + TRANSFORM(tnValue)\n"
            "    ENDFUNC\n"
            "    FUNCTION NoSimple\n"
            "        LPARAMETERS tnValue\n"
            "        cSequence = cSequence + '[nosimple:' + TRANSFORM(tnValue) + ']'\n"
            "        nNoSimpleSourceCalls = nNoSimpleSourceCalls + 1\n"
            "        RETURN 'nosimple:' + TRANSFORM(tnValue)\n"
            "    ENDFUNC\n"
            "ENDDEFINE\n"
            "DEFINE CLASS HandlerThing AS Custom\n"
            "    FUNCTION HandleBefore\n"
            "        LPARAMETERS tnValue\n"
            "        cSequence = cSequence + '[before:' + TRANSFORM(tnValue) + ']'\n"
            "        nBeforeCalls = nBeforeCalls + 1\n"
            "        RETURN\n"
            "    ENDFUNC\n"
            "    FUNCTION HandleAfter\n"
            "        LPARAMETERS tnValue\n"
            "        cSequence = cSequence + '[after:' + TRANSFORM(tnValue) + ']'\n"
            "        nAfterCalls = nAfterCalls + 1\n"
            "        RETURN\n"
            "    ENDFUNC\n"
            "    FUNCTION HandleNoSimple\n"
            "        LPARAMETERS tnValue\n"
            "        cSequence = cSequence + '[nosimplehandler:' + TRANSFORM(tnValue) + ']'\n"
            "        nNoSimpleCalls = nNoSimpleCalls + 1\n"
            "        RETURN\n"
            "    ENDFUNC\n"
            "ENDDEFINE\n");

        copperfin::runtime::PrgRuntimeSession session =
            copperfin::runtime::PrgRuntimeSession::create(make_runtime_session_options(main_path.string(), temp_root.string()));

        const auto state = session.run(copperfin::runtime::DebugResumeAction::continue_run);
        expect(state.completed,
               std::string("native BINDEVENT/RAISEEVENT script should complete: ") + state.message +
                   " @line=" + std::to_string(state.location.line));

        const auto check = [&](const std::string &name, const std::string &expected)
        {
            const auto it = state.globals.find(name);
            if (it == state.globals.end())
            {
                expect(false, name + " variable not found");
                return;
            }
            expect(copperfin::runtime::format_value(it->second) == expected,
                   name + " expected '" + expected + "' got '" + copperfin::runtime::format_value(it->second) + "'");
        };

        check("nbind1", "1");
        check("nbind2", "2");
        check("nbind3", "1");
        check("nbind4", "1");
        check("cdirectping", "ping:41");
        check("lraisedafter", "true");
        check("cdirectnosimple", "nosimple:5");
        check("lraisednosimple", "true");
        check("nunbindspecific", "1");
        check("lraisedpingafterunbind", "true");
        check("nunbindobject", "2");
        check("lraisedafterafterobjectunbind", "true");
        check("nbeforecalls", "1");
        check("nroutinecalls", "2");
        check("nsourcecalls", "2");
        check("naftercalls", "1");
        check("naftersourcecalls", "2");
        check("nnosimplecalls", "1");
        check("nnosimplesourcecalls", "2");
        check("csequence",
              "[before:41][source:41][routine:41][aftersource:7][after:7][nosimple:5][nosimple:6][nosimplehandler:6][source:9][routine:9][aftersource:8]");
        check("cplain", "plain");
        check("ldictset", "true");
        check("ndictcompare", "29");

        expect(state.ole_objects.size() == 4U,
               "native BINDEVENT/RAISEEVENT script should register source, handler, plain, and COM objects");
        if (state.ole_objects.size() == 4U)
        {
            expect(state.ole_objects[0].prog_id == "SourceThing",
                   "native BINDEVENT/RAISEEVENT should preserve the source class identity");
            expect(state.ole_objects[1].prog_id == "HandlerThing",
                   "native BINDEVENT/RAISEEVENT should preserve the handler class identity");
            expect(state.ole_objects[2].prog_id == "Empty",
                   "plain CREATEOBJECT should remain stable while native event binding lands");
            expect(state.ole_objects[3].prog_id == "Scripting.Dictionary",
                   "COM NEWOBJECT should remain stable while native event binding lands");
        }

        const bool has_bind_event = std::any_of(state.events.begin(), state.events.end(), [](const auto &event)
        {
            return event.category == "prg.event.bind";
        });
        const bool has_raise_event = std::any_of(state.events.begin(), state.events.end(), [](const auto &event)
        {
            return event.category == "prg.event.raise";
        });
        const bool has_delegate_event = std::any_of(state.events.begin(), state.events.end(), [](const auto &event)
        {
            return event.category == "prg.event.delegate";
        });
        expect(has_bind_event,
               "native BINDEVENT should emit a runtime bind event");
        expect(has_raise_event,
               "native RAISEEVENT should emit a runtime raise event");
        expect(has_delegate_event,
               "native event dispatch should emit delegate invocation events");

        fs::remove_all(temp_root, ignored);
    }

    void test_same_prg_native_raiseevent_handler_fault_does_not_disable_future_dispatch()
    {
        namespace fs = std::filesystem;
        const fs::path temp_root = fs::temp_directory_path() / "copperfin_native_prg_raiseevent_fault_recovery";
        std::error_code ignored;
        fs::remove_all(temp_root, ignored);
        fs::create_directories(temp_root);

        const fs::path main_path = temp_root / "native_raiseevent_fault_recovery.prg";
        write_text(
            main_path,
            "cSequence = ''\n"
            "nHandlerCalls = 0\n"
            "nSourceCalls = 0\n"
            "oSource = CREATEOBJECT('SourceThing')\n"
            "nBind = BINDEVENT(oSource, 'Ping', 'HandlePing')\n"
            "lCaught = .F.\n"
            "TRY\n"
            "    lFirstRaised = RAISEEVENT(oSource, 'Ping', 1)\n"
            "CATCH TO oErr\n"
            "    lCaught = .T.\n"
            "    cFirstError = oErr.Message\n"
            "ENDTRY\n"
            "lSecondRaised = RAISEEVENT(oSource, 'Ping', 2)\n"
            "RETURN\n"
            "PROCEDURE HandlePing\n"
            "    LPARAMETERS tnValue\n"
            "    nHandlerCalls = nHandlerCalls + 1\n"
            "    cSequence = cSequence + '[handler:' + TRANSFORM(tnValue) + ']'\n"
            "    IF nHandlerCalls = 1\n"
            "        1 / 0\n"
            "    ENDIF\n"
            "    RETURN\n"
            "ENDPROC\n"
            "DEFINE CLASS SourceThing AS Custom\n"
            "    FUNCTION Ping\n"
            "        LPARAMETERS tnValue\n"
            "        nSourceCalls = nSourceCalls + 1\n"
            "        cSequence = cSequence + '[source:' + TRANSFORM(tnValue) + ']'\n"
            "        RETURN 'ping:' + TRANSFORM(tnValue)\n"
            "    ENDFUNC\n"
            "ENDDEFINE\n");

        copperfin::runtime::PrgRuntimeSession session =
            copperfin::runtime::PrgRuntimeSession::create(make_runtime_session_options(main_path.string(), temp_root.string()));

        const auto state = session.run(copperfin::runtime::DebugResumeAction::continue_run);
        expect(state.completed,
               std::string("native RAISEEVENT fault-recovery script should complete: ") + state.message +
                   " @line=" + std::to_string(state.location.line));

        const auto check = [&](const std::string &name, const std::string &expected)
        {
            const auto it = state.globals.find(name);
            if (it == state.globals.end())
            {
                expect(false, name + " variable not found");
                return;
            }
            expect(copperfin::runtime::format_value(it->second) == expected,
                   name + " expected '" + expected + "' got '" + copperfin::runtime::format_value(it->second) + "'");
        };

        check("nbind", "1");
        check("lcaught", "true");
        check("lsecondraised", "true");
        check("nhandlercalls", "2");
        check("nsourcecalls", "2");
        check("csequence", "[source:1][handler:1][source:2][handler:2]");

        const auto first_error = state.globals.find("cfirsterror");
        expect(first_error != state.globals.end(),
               "faulting RAISEEVENT handler should populate the CATCH error message");

        fs::remove_all(temp_root, ignored);
    }

